108: 		if ((rv = match(ms, ml->magic, ml->nmagic, buf, nbytes, 0, mode,
109: 		    text, 0, indir_count, name_count,
110: 		    &printed_something, &need_separator, NULL)) != 0)
111: 			return rv;
112: 
113: 	return 0;
114: }
